public final class CompanionThreatMemoryService {
    private static final int MEMORY_TICKS = 120;
    private static final Map<UUID, ThreatMemory> MEMORIES = new HashMap<UUID, ThreatMemory>();

    private CompanionThreatMemoryService() {
    }

    public static void remember(LivingHurtEvent event) {
        LivingEntity livingEntity = event.getEntity();
        if (!(livingEntity instanceof ServerPlayer)) {
            return;
        }
        ServerPlayer player = (ServerPlayer)livingEntity;
        LivingEntity attacker = CompanionThreatMemoryService.sourceAttacker(event.getSource());
        if (attacker == null || attacker == player || attacker instanceof Player || CompanionEntityClassifier.isOwnedBy(player, (Entity)attacker)) {
            return;
        }
        MEMORIES.put(player.m_20148_(), new ThreatMemory(attacker.m_20148_(), (ResourceKey<Level>)attacker.m_9236_().m_46472_(), player.m_284548_().m_46467_() + 120L));
        CompanionTacticalOrderService.onOwnerHurt(player, attacker);
    }

    public static void handleIncomingDamage(LivingHurtEvent event) {
        if (VehicleManager.shouldCancelSwitchVehicleDamage(event.getEntity(), event.getSource())) {
            event.setAmount(0.0f);
            event.setCanceled(true);
            return;
        }
        CompanionThreatMemoryService.remember(event);
    }

    public static Optional<LivingEntity> findRecentThreat(ServerPlayer player, double range) {
        LivingEntity living;
        ThreatMemory memory = MEMORIES.get(player.m_20148_());
        if (memory == null) {
            return Optional.empty();
        }
        long now = player.m_284548_().m_46467_();
        if (now > memory.expiresAt() || !memory.dimension().equals((Object)player.m_9236_().m_46472_())) {
            MEMORIES.remove(player.m_20148_());
            return Optional.empty();
        }
        Entity entity = CompanionEntityLookup.findEntity(player.m_20194_(), memory.threatUuid()).orElse(null);
        if (!(entity instanceof LivingEntity) || (living = (LivingEntity)entity).m_9236_() != player.m_9236_() || !living.m_6084_() || living.m_20280_((Entity)player) > range * range) {
            return Optional.empty();
        }
        return Optional.of(living);
    }

    private static LivingEntity sourceAttacker(DamageSource source) {
        if (source == null) {
            return null;
        }
        Entity attacker = source.m_7639_();
        if (attacker instanceof LivingEntity) {
            LivingEntity living = (LivingEntity)attacker;
            return living;
        }
        Entity direct = source.m_7640_();
        if (direct instanceof LivingEntity) {
            LivingEntity living = (LivingEntity)direct;
            return living;
        }
        return null;
    }

    private record ThreatMemory(UUID threatUuid, ResourceKey<Level> dimension, long expiresAt) {
    }
